// ─── Vibration: get_fft_abs_data ─────────────────────────────────────

#[test]
fn golden_get_fft_abs_data_lengths() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    let (fft_abs, freqs, angles) = get_fft_abs_data(&signal, sr);
    let py_fft_abs = get_f64_array(&golden, &["get_fft_abs_data", "fft_abs"]);
    let py_freqs = get_f64_array(&golden, &["get_fft_abs_data", "freqs"]);
    let py_angles = get_f64_array(&golden, &["get_fft_abs_data", "angles"]);

    assert_eq!(fft_abs.len(), py_fft_abs.len(), "fft_abs length mismatch");
    assert_eq!(freqs.len(), py_freqs.len(), "freqs length mismatch");
    assert_eq!(angles.len(), py_angles.len(), "angles length mismatch");
}

#[test]
fn golden_get_fft_abs_data_freqs() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    let (_, freqs, _) = get_fft_abs_data(&signal, sr);
    let py_freqs = get_f64_array(&golden, &["get_fft_abs_data", "freqs"]);

    for (i, (&rust_f, &py_f)) in freqs.iter().zip(py_freqs.iter()).enumerate() {
        assert_close(rust_f, py_f, 1e-12, &format!("freqs[{}]", i));
    }
}

#[test]
fn golden_get_fft_abs_data_magnitude() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    let (fft_abs, _, _) = get_fft_abs_data(&signal, sr);
    let py_fft_abs = get_f64_array(&golden, &["get_fft_abs_data", "fft_abs"]);

    for (i, (&rust_v, &py_v)) in fft_abs.iter().zip(py_fft_abs.iter()).enumerate() {
        assert_close(rust_v, py_v, 1e-6, &format!("fft_abs[{}]", i));
    }
}

#[test]
fn golden_get_fft_abs_data_angles() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    let (_, _, angles) = get_fft_abs_data(&signal, sr);
    let py_angles = get_f64_array(&golden, &["get_fft_abs_data", "angles"]);

    for (i, (&rust_v, &py_v)) in angles.iter().zip(py_angles.iter()).enumerate() {
        // Phase angles can differ by 2*pi or have sign flips at very small magnitudes
        let diff = (rust_v - py_v).abs();
        let wrapped_diff = diff.min((diff - 2.0 * std::f64::consts::PI).abs());
        assert!(
            wrapped_diff < 1e-6,
            "angles[{}]: Rust={:.10e}, Python={:.10e}, diff={:.6e}",
            i,
            rust_v,
            py_v,
            wrapped_diff
        );
    }
}

// ─── Feature: time_domain_features ───────────────────────────────────

#[test]
fn golden_time_domain_features() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let py_td = get_f64_array(&golden, &["time_domain_features"]);

    let rust_td = time_domain_features(&signal);

    assert_eq!(rust_td.len(), py_td.len(), "time_domain feature count mismatch");

    let labels = [
        "max", "min", "mean", "std", "sqrt_amplitude", "rms", "peak_peak",
        "skewness", "kurtosis", "crest", "clearance", "shape", "impulse",
    ];

    for (i, (&rust_v, &py_v)) in rust_td.iter().zip(py_td.iter()).enumerate() {
        assert_close(
            rust_v,
            py_v,
            1e-6,
            &format!("time_domain[{}] ({})", i, labels[i]),
        );
    }
}

// ─── Feature: freq_domain_features ───────────────────────────────────

#[test]
fn golden_freq_domain_features() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    // Use Rust FFT output (same as what Python golden data used)
    let (fft_abs, freqs, _) = get_fft_abs_data(&signal, sr);

    // But we should use Python's FFT output for a fair comparison
    let py_fft_abs = get_f64_array(&golden, &["get_fft_abs_data", "fft_abs"]);
    let py_freqs = get_f64_array(&golden, &["get_fft_abs_data", "freqs"]);
    let py_fd = get_f64_array(&golden, &["freq_domain_features"]);

    // Test using Python's FFT data as input (isolates freq_domain_features logic)
    let rust_fd_from_py = freq_domain_features(&py_fft_abs, &py_freqs);

    let labels = [
        "f12_mean", "f13_variance", "f14_skewness", "f15_kurtosis",
        "f16_centroid", "f17_rms_spread", "f18_rms_freq", "f19_fourth_moment",
        "f20_regularity", "f21_spread_ratio", "f22_weighted_skew", "f23_weighted_kurt",
    ];

    assert_eq!(rust_fd_from_py.len(), py_fd.len(), "freq_domain feature count mismatch");

    for (i, (&rust_v, &py_v)) in rust_fd_from_py.iter().zip(py_fd.iter()).enumerate() {
        assert_close(
            rust_v,
            py_v,
            1e-6,
            &format!("freq_domain[{}] ({})", i, labels[i]),
        );
    }

    // Also test end-to-end: Rust FFT → Rust freq features
    let rust_fd_e2e = freq_domain_features(&fft_abs, &freqs);
    assert_eq!(rust_fd_e2e.len(), 12);
    for (i, (&rust_v, &py_v)) in rust_fd_e2e.iter().zip(py_fd.iter()).enumerate() {
        assert_close(
            rust_v,
            py_v,
            1e-4, // Looser tolerance for end-to-end due to FFT precision differences
            &format!("freq_domain_e2e[{}] ({})", i, labels[i]),
        );
    }
}

// ─── End-to-end pipeline test ────────────────────────────────────────

#[test]
fn golden_end_to_end_pipeline() {
    let golden = load_golden();
    let signal = get_signal(&golden);
    let sr = golden["sampling_rate"].as_f64().unwrap();

    // Full pipeline: signal → FFT → both feature sets
    let (fft_abs, freqs, _) = get_fft_abs_data(&signal, sr);
    let td = time_domain_features(&signal);
    let fd = freq_domain_features(&fft_abs, &freqs);

    // Sanity checks
    assert_eq!(td.len(), 13);
    assert_eq!(fd.len(), 12);

    // RMS from time_domain should roughly match acc_rms from vibration
    // (not exact since acceleration_rms applies frequency filtering)
    let td_rms = td[5];
    assert!(td_rms > 0.0, "RMS should be positive");

    // Centroid should be within Nyquist
    let nyquist = sr / 2.0;
    let centroid = fd[4];
    assert!(
        centroid > 0.0 && centroid < nyquist,
        "Centroid {} should be within (0, {})",
        centroid,
        nyquist
    );
}
